ssize_t get_acl_uncached(struct inode *inode, void *buf, size_t buflen) {
    struct page **pages = NULL;
    ssize_t ret = 0;
    size_t num_pages = (buflen + PAGE_SIZE - 1) / PAGE_SIZE;
    int i;

    pages = kmalloc_array(num_pages, sizeof(struct page *), GFP_KERNEL);
    if (!pages)
        return -ENOMEM;

    for (i = 0; i < num_pages; i++) {
        pages[i] = alloc_page(GFP_KERNEL);
        if (!pages[i]) {
            ret = -ENOMEM;
            goto out_free_pages;
        }
    }

    // Prepare message for the NFS call
    struct nfs4_getacl_msg msg;
    msg.inode = inode;
    msg.pages = pages;
    msg.num_pages = num_pages;

    ret = nfs4_call_getacl(&msg);
    if (ret < 0)
        goto out_free_pages;

    // Copy the ACL data from the pages into the buffer
    for (i = 0; i < num_pages; i++) {
        void *page_addr = page_address(pages[i]);
        size_t copy_len = min(PAGE_SIZE, buflen);

        memcpy(buf, page_addr, copy_len);
        buf += copy_len;
        buflen -= copy_len;

        if (buflen == 0)
            break;
    }

out_free_pages:
    for (i = 0; i < num_pages; i++) {
        if (pages[i])
            __free_page(pages[i]);
    }
    kfree(pages);

    return (ret < 0) ? ret : (ssize_t)(num_pages * PAGE_SIZE);
}

ssize_t get_acl_uncached(struct inode *inode, void *buf, size_t buflen) {
    struct page **pages;
    ssize_t ret = 0;
    int npages = (buflen + PAGE_SIZE - 1) >> PAGE_SHIFT;
    int i;

    pages = kmalloc(npages * sizeof(struct page *), GFP_KERNEL);
    if (!pages)
        return -ENOMEM;

    for (i = 0; i < npages; i++) {
        pages[i] = alloc_page(GFP_KERNEL);
        if (!pages[i]) {
            while (i--)
                __free_page(pages[i]);
            kfree(pages);
            return -ENOMEM;
        }
    }

    ret = nfs_call_getacl(inode, pages, buflen);
    if (ret < 0)
        goto out;

    if (ret > buflen) {
        ret = -EINVAL;
        goto out;
    }

    for (i = 0; i < npages && buflen > 0; i++) {
        size_t len = min_t(size_t, PAGE_SIZE, buflen);
        memcpy(buf, page_address(pages[i]), len);
        buf = (char *)buf + len;
        buflen -= len;
    }

out:
    for (i = 0; i < npages; i++)
        __free_page(pages[i]);
    kfree(pages);
    return ret;
}

ssize_t get_acl_no_cache(struct inode *inode, void *buf, size_t buflen) {
    struct page **pages;
    ssize_t ret = 0;
    size_t num_pages = (buflen + PAGE_SIZE - 1) / PAGE_SIZE;

    pages = kmalloc(num_pages * sizeof(struct page *), GFP_KERNEL);
    if (!pages)
        return -ENOMEM;

    for (size_t i = 0; i < num_pages; i++) {
        pages[i] = alloc_page(GFP_KERNEL);
        if (!pages[i]) {
            while (i--) {
                __free_page(pages[i]);
            }
            kfree(pages);
            return -ENOMEM;
        }
    }

    // Prepare and send the synchronous NFS call to retrieve the ACL
    ret = nfs_call_getacl(inode, pages, num_pages);
    if (ret < 0) {
        goto out_free_pages;
    }

    // If the ACL was successfully retrieved, copy the data to the buffer
    size_t copied = 0;
    for (size_t i = 0; i < num_pages && copied < buflen; i++) {
        size_t copy_len = min(PAGE_SIZE, buflen - copied);
        memcpy(buf + copied, page_address(pages[i]), copy_len);
        copied += copy_len;
    }

    ret = copied;

out_free_pages:
    for (size_t i = 0; i < num_pages; i++) {
        __free_page(pages[i]);
    }
    kfree(pages);

    return ret;
}

ssize_t get_acl_no_cache(struct inode *inode, void *buf, size_t buflen) {
    struct page **pages;
    int num_pages = (buflen + PAGE_SIZE - 1) / PAGE_SIZE;
    ssize_t ret = 0;
    size_t i;

    pages = kmalloc(num_pages * sizeof(struct page *), GFP_KERNEL);
    if (!pages)
        return -ENOMEM;

    for (i = 0; i < num_pages; i++) {
        pages[i] = alloc_page(GFP_KERNEL);
        if (!pages[i]) {
            while (i--)
                __free_page(pages[i]);
            kfree(pages);
            return -ENOMEM;
        }
    }

    ret = nfs_call_get_acl(inode, pages, num_pages);
    if (ret < 0)
        goto free_pages;

    ret = 0;
    for (i = 0; i < num_pages && ret < buflen; i++) {
        size_t copy_len = min(PAGE_SIZE, buflen - ret);
        void *page_addr = kmap(pages[i]);
        memcpy(buf + ret, page_addr, copy_len);
        kunmap(pages[i]);
        ret += copy_len;
    }

free_pages:
    for (i = 0; i < num_pages; i++)
        __free_page(pages[i]);

    kfree(pages);

    return ret;
}

